import sys,json,pathlib,urllib.request
p=pathlib.Path('/Users/yzydalshmry/Desktop/QC-Operations-Laboratory-Management-System/.env')
k=next((s.split('=',1)[1].strip().strip(chr(34)+chr(39)) for s in p.read_text().splitlines() if s.startswith('STITCH_API_KEY=')),None)
if not k: raise SystemExit('Stitch credential is not configured')
for line in sys.stdin:
 try:
  m=json.loads(line)
  if 'id' not in m: continue
  req=urllib.request.Request('https://stitch.googleapis.com/mcp',data=json.dumps(m).encode(),headers={'Content-Type':'application/json','Accept':'application/json','X-Goog-Api-Key':k})
  with urllib.request.urlopen(req,timeout=7200) as r: result=json.load(r)
  print(json.dumps(result),flush=True)
 except Exception:
  if isinstance(locals().get('m'),dict) and 'id' in m: print(json.dumps({'jsonrpc':'2.0','id':m['id'],'error':{'code':-32603,'message':'Stitch upstream request failed; credentials and upstream details withheld'}}),flush=True)
